import Foundation

// Stable source templates keep runtime values out of translation lookup keys.
struct LocalizedPhrase: ExpressibleByStringLiteral, ExpressibleByStringInterpolation {
    let key: String
    let values: [String]
    init(stringLiteral value: String) { key = value; values = [] }
    init(stringInterpolation: StringInterpolation) { key = stringInterpolation.key; values = stringInterpolation.values }
    struct StringInterpolation: StringInterpolationProtocol {
        var key = ""
        var values: [String] = []
        init(literalCapacity: Int, interpolationCount: Int) { values.reserveCapacity(interpolationCount) }
        mutating func appendLiteral(_ literal: String) { key += literal }
        mutating func appendInterpolation<T>(_ value: T) { key += "{\(values.count)}"; values.append(String(describing: value)) }
    }
    func render(_ template: String) -> String {
        // Replace only placeholders in the template, never placeholders inside user values.
        var output = "", cursor = template.startIndex
        while cursor < template.endIndex {
            if template[cursor] == "{", let end = template[cursor...].firstIndex(of: "}"),
               let index = Int(template[template.index(after: cursor)..<end]), values.indices.contains(index) {
                output += values[index]; cursor = template.index(after: end)
            } else { output.append(template[cursor]); cursor = template.index(after: cursor) }
        }
        return output
    }
}

